1	use encoding_rs::{Decoder, Encoder, Encoding};
2	use std::fmt;
3	use std::io;
4	
5	use crate::util::ConsumeBuf;
6	
7	const MAX_OUTPUT: usize = 4096;
8	
9	/// Charset transcoder
10	pub(crate) struct CharCodec<R> {
11	    reader: R,
12	    input_buf: ConsumeBuf,
13	    dec: Option<Decoder>,
14	    enc: Option<Encoder>,
15	    output_buf: ConsumeBuf,
16	    reached_end: bool,
17	}
18	
19	impl<R> CharCodec<R>
20	where
21	    R: io::Read,
22	{
23	    pub fn new(reader: R, from: &'static Encoding, to: &'static Encoding) -> Self {
24	        CharCodec {
25	            reader,
26	            input_buf: ConsumeBuf::new(8192),
27	            dec: Some(from.new_decoder()),
28	            enc: if to == encoding_rs::UTF_8 {
29	                None
30	            } else {
31	                Some(to.new_encoder())
32	            },
33	            output_buf: ConsumeBuf::new(MAX_OUTPUT),
34	            reached_end: false,
35	        }
36	    }
37	}
38	
39	impl<R: io::Read> io::Read for CharCodec<R> {
40	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
41	        if self.reached_end && self.output_buf.unconsumed().is_empty() {
42	            return Ok(0);
43	        }
44	
45	        // Ensure we have at least 4 bytes of input to decode, or we've reached EOF
46	        while self.input_buf.unconsumed().len() < 4 && !self.reached_end {
47	            let free = self.input_buf.free_mut();
48	            let n = self.reader.read(free)?;
49	            if n == 0 {
50	                // Reached EOF
51	                self.reached_end = true;
52	                break;
53	            }
54	            self.input_buf.add_filled(n);
55	        }
56	
57	        let input = self.input_buf.unconsumed();
58	
59	        if self.output_buf.free_mut().len() < 4 {
60	            self.output_buf.add_space(1024);
61	        }
62	        let output = self.output_buf.free_mut();
63	
64	        if let Some(dec) = &mut self.dec {
65	            let (_, input_used, output_used, _had_errors) =
66	                dec.decode_to_utf8(input, output, self.reached_end);
67	
68	            self.input_buf.consume(input_used);
69	            self.output_buf.add_filled(output_used);
70	
71	            if self.reached_end {
72	                // Can't be used again
73	                self.dec = None;
74	            }
75	        }
76	
77	        // The output_buf contains UTF-8 data produced by decode_to_utf8(), which guarantees
78	        // char boundaries. When we have an encoder (converting UTF-8 to another encoding),
79	        // encode_from_utf8() returns input_used on char boundaries, so consume() maintains
80	        // the invariant. When we have no encoder (already UTF-8), we copy arbitrary byte
81	        // amounts, but that's safe because we never need to parse it as UTF-8 - we just
82	        // pass the bytes through.
83	        let bytes = self.output_buf.unconsumed();
84	
85	        let amount = if let Some(enc) = &mut self.enc {
86	            // unwrap is ok because it is on a char boundary, and non-utf8 chars have been replaced
87	            let utf8 = std::str::from_utf8(bytes).unwrap();
88	            let (_, input_used, output_used, _) = enc.encode_from_utf8(utf8, buf, self.reached_end);
89	            self.output_buf.consume(input_used);
90	
91	            if self.reached_end {
92	                // Can't be used again
93	                self.enc = None;
94	            }
95	
96	            output_used
97	        } else {
98	            // No encoder, we want utf8
99	            let max = bytes.len().min(buf.len());
100	            buf[..max].copy_from_slice(&bytes[..max]);
101	            self.output_buf.consume(max);
102	            max
103	        };
104	
105	        Ok(amount)
106	    }
107	}
