109	impl<R> fmt::Debug for CharCodec<R> {
110	    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
111	        write!(
112	            f,
113	            "CharCodec {{ from: {}, to: {} }}",
114	            self.dec
115	                .as_ref()
116	                .map(|d| d.encoding().name())
117	                .unwrap_or(encoding_rs::UTF_8.name()),
118	            self.enc
119	                .as_ref()
120	                .map(|e| e.encoding())
121	                .unwrap_or(encoding_rs::UTF_8)
122	                .name()
123	        )
124	    }
125	}
