24	impl<In: Transport> Connector<In> for TestConnector {
25	    type Out = Either<In, TestTransport>;
26	
27	    fn connect(
28	        &self,
29	        details: &ConnectionDetails,
30	        chained: Option<In>,
31	    ) -> Result<Option<Self::Out>, Error> {
32	        if chained.is_some() {
33	            // The chained connection overrides whatever we were to open here.
34	            trace!("Skip");
35	            return Ok(chained.map(Either::A));
36	        }
37	        let config = details.config;
38	
39	        // Let ConnectProxyConnector handle the target connection. Its recursive
40	        // connection to the proxy uses a config without a proxy and is intercepted
41	        // by this connector, keeping the entire test in memory.
42	        let use_connect_proxy = config.connect_proxy_uri().is_some()
43	            && config
44	                .proxy()
45	                .is_some_and(|proxy| !proxy.is_no_proxy(details.uri));
46	        if use_connect_proxy {
47	            trace!("Defer to CONNECT proxy");
48	            return Ok(None);
49	        }
50	
51	        let uri = details.uri.clone();
52	        debug!("Test uri: {}", uri);
53	
54	        let buffers = LazyBuffers::new(config.input_buffer_size(), config.output_buffer_size());
55	
56	        let (tx1, rx1) = mpsc::sync_channel(10);
57	        let (tx2, rx2) = mpsc::sync_channel(10);
58	
59	        let mut handlers = HANDLERS.with(|h| (*h).borrow().clone());
60	        setup_default_handlers(&mut handlers);
61	
62	        thread::spawn(|| test_run(uri, rx1, tx2, handlers));
63	
64	        let transport = TestTransport {
65	            buffers,
66	            tx: tx1,
67	            rx: SyncReceiver(Mutex::new(rx2)),
68	            connected_tx: true,
69	            connected_rx: true,
70	        };
71	
72	        Ok(Some(Either::B(transport)))
73	    }
74	}
