105	pub fn set_handler(pattern: &'static str, status: u16, headers: &[(&str, &str)], body: &[u8]) {
106	    // Convert headers to a big string
107	    let mut headers_s = String::new();
108	    for (k, v) in headers {
109	        headers_s.push_str(&format!("{}: {}\r\n", k, v));
110	    }
111	
112	    // Convert body to an owned vec
113	    let body = body.to_vec();
114	
115	    let handler = TestHandler::new(pattern, move |_uri, _req, w| {
116	        write!(
