118	            "HTTP/1.1 {} OK\r\n\
119	            {}\
120	            \r\n",
121	            status, headers_s
122	        )?;
123	        w.write_all(&body)
124	    });
125	
126	    HANDLERS.with(|h| (*h).borrow_mut().push(handler));
127	}
