196	fn test_run(
197	    uri: Uri,
198	    rx: Receiver<Vec<u8>>,
199	    tx: mpsc::SyncSender<Vec<u8>>,
200	    handlers: Vec<TestHandler>,
201	) {
202	    let mut reader = SaneBufReader(Some(RxRead(rx)), vec![]);
203	    let mut writer = TxWrite(tx);
204	    let uri_s = uri.to_string();
205	
206	    let req = loop {
207	        let input = reader.fill_buf().expect("test fill_buf");
208	        let maybe = try_parse_request::<100>(input).expect("test parse request");
209	        if let Some((amount, req)) = maybe {
210	            reader.consume(amount);
211	            break req;
212	        } else {
213	            continue;
214	        }
215	    };
216	
217	    for handler in handlers {
218	        if uri_s.contains(handler.pattern) {
219	            match handler.handler {
220	                Handler::Http(handler) => {
221	                    handler(uri, req, &mut writer).expect("test handler to not fail")
222	                }
223	                #[cfg(feature = "_ring")]
224	                Handler::TlsTunnel(handler) => handler(uri, req, &mut reader, &mut writer)
225	                    .expect("test TLS tunnel handler to not fail"),
226	            }
227	            return;
228	        }
229	    }
230	
231	    panic!("test server unhandled url: {}", uri);
232	}
