        let mut res = crate::get("https://my.test/cs_limit").call().unwrap();
        let s = res
            .body_mut()
            .with_config()
            .limit(12)
            .read_to_string()
            .unwrap();
        assert_eq!(s, "\u{20AC}".repeat(4));
        assert_eq!(s.len(), 12);

        // One output byte less must fail, even though the wire body is only
        // 4 bytes.
        set_handler(
            "/cs_limit",
            200,
            &[(
                "content-type",
                "text/plain; charset=iso-8859-15",
            )],
            &body,
        );
        let mut res = crate::get("https://my.test/cs_limit").call().unwrap();
        let err = res
            .body_mut()
            .with_config()
            .limit(11)
            .read_to_string()
            .unwrap_err();
        assert!(matches!(err, Error::BodyExceedsLimit(11)), "got {err:?}");
    }

    // The limit has the same meaning over chunked transfer as over
    // Content-Length.
    #[test]
    fn limit_chunked_exact_and_over() {
        init_test_log();

        let chunked = "5\r\nhello\r\n1\r\n!\r\n0\r\n\r\n";
        set_handler(
            "/chunked_limit",
            200,
            &[("transfer-encoding", "chunked")],
            chunked.as_bytes(),
        );

        let mut res = crate::get("https://my.test/chunked_limit")
            .call()
            .unwrap();
        let v = res
            .body_mut()
            .with_config()
            .limit(6)
            .read_to_vec()
            .unwrap();
        assert_eq!(v, b"hello!");

        set_handler(
            "/chunked_limit",
            200,
            &[("transfer-encoding", "chunked")],
            chunked.as_bytes(),
        );
        let mut res = crate::get("https://my.test/chunked_limit")
            .call()
            .unwrap();
        let err = res
            .body_mut()
            .with_config()
            .limit(5)
            .read_to_vec()
            .unwrap_err();
        assert!(matches!(err, Error::BodyExceedsLimit(5)));
    }

    // The limit has the same meaning for a close-delimited (HTTP/1.0) body.
    #[test]
    fn limit_close_delimited_exact_and_over() {
        init_test_log();

        crate::transport::set_handler_raw("/close_limit", move |w| {
            write!(w, "HTTP/1.0 200 OK\r\nContent-Type: text/plain\r\n\r\nhello!<hangup>")
        });

        let mut res = crate::get("https://my.test/close_limit").call().unwrap();
        let v = res
            .body_mut()
            .with_config()
            .limit(6)
            .read_to_vec()
            .unwrap();
        assert_eq!(v, b"hello!");

        crate::transport::set_handler_raw("/close_limit2", move |w| {
            write!(w, "HTTP/1.0 200 OK\r\nContent-Type: text/plain\r\n\r\nhello!<hangup>")
        });
        let mut res = crate::get("https://my.test/close_limit2").call().unwrap();
        let err = res
            .body_mut()
            .with_config()
            .limit(5)
            .read_to_vec()
            .unwrap_err();
        assert!(matches!(err, Error::BodyExceedsLimit(5)));
    }

    // An unrecognized content-encoding is passed through undecoded; the limit
    // still applies to the (final, unchanged) output bytes.
    #[test]
    fn unknown_content_encoding_limit_applies_to_raw_bytes() {
        init_test_log();
        set_handler(
            "/unknown_ce",
            200,
            &[
                ("content-encoding", "deflate"),
                ("content-length", "5"),
            ],
            b"hello",
        );
        let mut res = crate::get("https://my.test/unknown_ce")
            .call()
            .unwrap();
        let v = res
            .body_mut()
            .with_config()
            .limit(5)
            .read_to_vec()
            .unwrap();
        assert_eq!(v, b"hello");
    }
}

